	QUATERNION: { id: 20, name: 'Quaternion' },
	OBJECT3D: { id: 21, name: 'Object3D' },

	VECTOR4: { id: 22, name: 'Vector 4' },

	ENVIRONMENTSETTINGS: { id: 23, name: 'Environment Settings' },

	CUBETEXTURE: { id: 24, name: 'CubeTexture' },
