	this.state = { url: '' }

	this.input_slots = []

	this.output_slots = [{
		name: 'geometry',
		dt: core.datatypes.GEOMETRY,
		array: true
	},
	{
		name: 'materials',
		dt: core.datatypes.MATERIAL,
		array: true
	}]

