WorldEditorOrthographicCamera.prototype.update = function() {
	var distance = this.camera.position.length()

	var zoom = 1 / distance

	if (this.camera.zoom !== zoom) {
		this.camera.zoom = zoom

		this.camera.updateProjectionMatrix()
	}
}

