E2.p = E2.plugins["absolute_modulator"] = function(core, node)
{

	this.desc = 'Emit the absolute value of the input.';
	
	this.input_slots = [ 
		{ name: 'value', dt: core.datatypes.FLOAT, desc: 'Positive or negative input value', def: 0.0 }
	];
	
	this.output_slots = [
		{ name: 'result', dt: core.datatypes.FLOAT, desc: 'Positive output value', def: 0.0 }
	];
};

E2.p.prototype.reset = function()
{
	this.input_val = 0.0;
	this.output_val = 0.0;
};

E2.p.prototype.update_input = function(slot, data)
{
	this.input_val = data;
};	

E2.p.prototype.update_state = function()
{
	this.output_val = Math.abs(this.input_val);
};

E2.p.prototype.update_output = function(slot)
{
	return this.output_val;
};

;
E2.p = E2.plugins["accumulate_modulator"] = function(core, node)
{
	this.desc = 'Every input <b>value</b> is accumulated in an internal buffer (which resets to zero on playback stop).';
	
	this.input_slots = [
		{ name: 'value', dt: core.datatypes.FLOAT, desc: 'A small value to be accumulated in an internal buffer.', def: 0.0 },
		{ name: 'reset', dt: core.datatypes.FLOAT, desc: 'Send a value to this slot to reset the accumulator to that value.', def: 0.0 }
	];
	
	this.output_slots = [
		{ name: 'value', dt: core.datatypes.FLOAT, desc: 'The current value of the accumulation buffer.', def: 0.0 }
	];
	
	this.state = { value: 0.0 };
};

E2.p.prototype.reset = function()
{
	this.updated = true;
};

E2.p.prototype.update_input = function(slot, data)
{
	if(slot.index === 0)
		this.state.value += data;
	else
		this.state.value = data;
};	

E2.p.prototype.update_output = function(slot)
{
	return this.state.value;
};	


;
E2.p = E2.plugins["action_button"] = function(core, node)
{
	this.desc = 'Push button that emits true when it is clicked.';
	
	this.input_slots = [];
	
	this.output_slots = [
		{ name: 'bool', dt: core.datatypes.BOOL, desc: 'True once each time the button is clicked.', def: false }
	];
	
	this.node = node;
	this.value = false;
	this.output_value = false;
};

E2.p.prototype.reset = function()
{
	this.value = false;
	this.output_value = false;
};

E2.p.prototype.create_ui = function()
{
	var inp = makeButton('Click', '', 'fxtrigger');
	
	inp.click(function(self) { return function(e) 
	{
		self.output_value = false;
		self.value = true;
		self.updated = true;
	}}(this));
	
	return inp;
};

E2.p.prototype.update_state = function()
{
	this.updated = this.output_value || this.value;
	this.output_value = this.value;
	this.value = false;
};

E2.p.prototype.update_output = function(slot)
{
	return this.output_value;
};

