E2.p = E2.plugins["grid_mesh_generator"] = function(core, node)
{
	this.desc = 'Create a planar grid mesh in the XY-plane of unit size.';
	
	this.input_slots = [
		{ name: 'x res', dt: core.datatypes.FLOAT, desc: 'X resolution.', lo: 2, hi: 250, def: 10 },
		{ name: 'y res', dt: core.datatypes.FLOAT, desc: 'Y resolution.', lo: 2, hi: 250, def: 10 }
	];
	
	this.output_slots = [
		{ name: 'mesh', dt: core.datatypes.MESH, desc: 'Grid mesh.' }
	];
	
	this.gl = core.renderer.context;
	this.state = { x_res: 10, y_res: 10 };
	this.mesh = null;
};

E2.p.prototype.reset = function()
{
	this.updated = true;
};

E2.p.prototype.update_input = function(slot, data)
{
	var v = Math.floor(data);
	
	if(v < 2)
		return;
	
	v = v > 250 ? 250 : v;
	
	if(slot.index === 0 && this.state.x_res !== v)
	{
		this.state.x_res = v;
		this.dirty = true;
	}
	else if(slot.index === 1 && this.state.y_res !== v)
	{
		this.state.y_res = v;
		this.dirty = true;
	}
};

E2.p.prototype.update_state = function()
{
	if(this.dirty)
		this.generate_mesh();
};

E2.p.prototype.update_output = function(slot)
{
	return this.mesh;
};

E2.p.prototype.generate_mesh = function()
{
	var gl = this.gl;
	
	this.mesh = new Mesh(gl, gl.LINES, null);
	
	var v_data = [];
	
	for(var y = 0; y < this.state.y_res + 1; y++)
	{
		var ofs = (y / (this.state.y_res / 2.0)) - 1.0;
		
		v_data.push(-1.0);		
		v_data.push(ofs);		
		v_data.push(0.0);		
		v_data.push(1.0);		
		v_data.push(ofs);		
		v_data.push(0.0);		
	}

	for(var x = 0; x < this.state.x_res + 1; x++)
	{
		var ofs = (x / (this.state.x_res / 2.0)) - 1.0;
		
		v_data.push(ofs);		
		v_data.push(-1.0);		
		v_data.push(0.0);		
		v_data.push(ofs);		
		v_data.push(1.0);		
		v_data.push(0.0);		
	}

	(this.mesh.vertex_buffers['VERTEX'] = new VertexBuffer(gl, VertexBuffer.vertex_type.VERTEX)).bind_data(v_data);
	this.mesh.generate_shader();
	this.dirty = false;
};

E2.p.prototype.state_changed = function(ui)
{
	if(!ui)
		this.generate_mesh();
};

;
E2.p = E2.plugins["gte_modulator"] = function(core, node)
{
	this.desc = 'Emits true if the supplied <b>value</b> is larger than or equal to <b>reference</b> and false otherwise.';
	
	this.input_slots = [ 
		{ name: 'value', dt: core.datatypes.FLOAT, desc: 'Input value to be compared.', def: 0.0 },
		{ name: 'reference', dt: core.datatypes.FLOAT, desc: 'Reference to compare <b>value</b> to.', def: 0.0 } 
	];
	
	this.output_slots = [
		{ name: 'bool', dt: core.datatypes.BOOL, desc: 'Emits true if <b>value</b> is larger than or equal to <b>reference</b>.', def: false }
	];
};

E2.p.prototype.reset = function()
{
	this.value = 0.0;
	this.ref = 0.0;
	this.state = null;
};

E2.p.prototype.update_input = function(slot, data)
{
	if(slot.index === 0)
		this.value = data;
	else
		this.ref = data;
};	

E2.p.prototype.update_state = function()
{
	var nst = this.value >= this.ref;
	
	if(nst !== this.state)
		this.state = nst;
	else
		this.updated = false;
};

E2.p.prototype.update_output = function(slot)
{
	return this.state;
};

;
E2.p = E2.plugins["if_else_modulator"] = function(core, node)
{
	this.desc = 'Emits <b>true value</b> if <b>condition</b> is true and <b>false value</b> otherwise. The output only updates when the <b>condition</b> or relavant input value does. Any incoming data-flow to the value slot excluded by <b>condition</b> does not result in data emission.';
	
	this.input_slots = [ 
		{ name: 'condition', dt: core.datatypes.BOOL, desc: 'Send true to route <b>true value</b> to the output and false to route <b>false value</b>.', def: false },
		{ name: 'true value', dt: core.datatypes.ANY, desc: 'Value to be send to output if <b>condition</b> is true', def: null } ,
		{ name: 'false value', dt: core.datatypes.ANY, desc: 'Value to be send to output if <b>condition</b> is false', def: null  }
	];
	
	this.output_slots = [
		{ name: 'value', dt: core.datatypes.ANY, desc: 'Emits <b>true value</b> if <b>condition</b> is true and <b>false value</b> otherwise.', def: 'False value' }
	];
	
	this.lsg = new LinkedSlotGroup(core, node, [this.input_slots[1], this.input_slots[2]], [this.output_slots[0]]);
	this.yes = this.no = null;
	this.initial_run = true;
};

E2.p.prototype.reset = function()
{
	this.initial_run = true;
	delete this.input_slots[1].inactive;
	delete this.input_slots[2].inactive;
}

E2.p.prototype.connection_changed = function(on, conn, slot)
{
	if(this.lsg.connection_changed(on, conn, slot))
		this.yes = this.no = this.lsg.core.get_default_value(this.lsg.dt);
};

E2.p.prototype.update_input = function(slot, data)
{
	if(slot.index === 0)
	{
		this.condition = data;
		
		if(!this.initial_run)
		{
			delete this.input_slots[this.condition ? 1 : 2].inactive;
			this.input_slots[this.condition ? 2 : 1].inactive = true;
		}
		else
			this.initial_run = false;
	}
	else if(slot.index === 1)
		this.yes = data;
	else
		this.no = data;
};	

E2.p.prototype.update_output = function(slot)
{
	return this.condition ? this.yes : this.no;
};

E2.p.prototype.state_changed = function(ui)
{
	if(!ui)
		this.yes = this.no = this.lsg.infer_dt();
};

