(function() {

function RunTimeEventReadPlugin(core, node) {
	this.input_slots = [{
		name: 'eventName',
		dt: E2.dt.TEXT
	}]

	this.output_slots = [
		{
			name: 'triggered',
			dt: E2.dt.BOOL
		},
		{
			name: 'data',
			dt: E2.dt.ANY
		}
	]

	this.node = node

	this.value = null
	this.frames = 0
	this.triggered = false
	this._handleMessageBound = this._handleMessage.bind(this)

	this.lsg = new LinkedSlotGroup(core, node, 
		[], [this.output_slots[0]])
}

RunTimeEventReadPlugin.prototype.connection_changed = function(on, conn, slot) {
	if (this.lsg.connection_changed(on, conn, slot))
		this.value = this.lsg.core.get_default_value(this.lsg.dt)

	this.output_slots[0].array = false
}

RunTimeEventReadPlugin.prototype._handleMessage = function(messageData) {
	this.value = messageData
	this.frames = 0
	this.triggered = true
	this.node.queued_update = 1
	this.updated = true
}

RunTimeEventReadPlugin.prototype.update_input = function(slot, data) {
	if (slot.name === 'eventName') {
		if (this.eventName) {
			E2.core.runtimeEvents.off(this.eventName,
				this._handleMessageBound)
		}

		this.eventName = data

		E2.core.runtimeEvents.on(this.eventName,
			this._handleMessageBound)
	}
}

RunTimeEventReadPlugin.prototype.update_state = function() {
	if (this.frames++ > 0) {
		this.triggered = false
		this.value = this.lsg.core.get_default_value(this.lsg.dt)
	}
}

RunTimeEventReadPlugin.prototype.update_output = function(slot) {
	if (slot.index === 0)
		return this.triggered

	return this.value
}

RunTimeEventReadPlugin.prototype.state_changed = function() {
	this.lsg.infer_dt()
	this.value = this.lsg.core.get_default_value(this.lsg.dt)
}

E2.plugins.runtime_event_read = RunTimeEventReadPlugin

})()


;
(function() {

function RunTimeEventWritePlugin() {
	this.input_slots = [{
		name: 'emit',
		dt: E2.dt.BOOL,
		desc: 'disable / enable emitting',
		def: true
	},
	{
		name: 'eventName',
		dt: E2.dt.TEXT
	},
	{
		name: 'data',
		dt: E2.dt.ANY
	}]
	
	this.output_slots = []

	this.desc = 'Emit a single runtime event when the data-input changes ' +
				'behaviour can be controlled by the emit-input. When emit becomes ' +
				'true, any data not yet sent will be emitted.'
}

RunTimeEventWritePlugin.prototype.update_input = function(slot, data) {
	if (slot.name === 'emit') {
		this.emitActive = data
	}

	if (slot.name === 'eventName') {
		this.eventName = data
	}

	if (slot.name === 'data') {
		this.value = data
	}

	this.hasNewData = true
}

RunTimeEventWritePlugin.prototype.update_state = function() {
	if (this.hasNewData && this.eventName && this.value !== undefined && this.emitActive) {
		E2.core.runtimeEvents.emit(this.eventName, this.value)

		this.hasNewData = false
	}
}

E2.plugins.runtime_event_write = RunTimeEventWritePlugin

})()
;
(function() {

	function RunTimeEventWriteContinuousPlugin() {
		this.input_slots = [{
			name: 'emit',
			dt: E2.dt.BOOL,
			desc: 'disable / enable emitting',
			def: true
		},
		{
			name: 'eventName',
			dt: E2.dt.TEXT
		},
		{
			name: 'data',
			dt: E2.dt.ANY
		}]

		this.output_slots = []

		this.desc = 'Emit one event on every frame for as long as ' +
					'the emit-input remaing true.'
	}

	RunTimeEventWriteContinuousPlugin.prototype.update_input = function(slot, data) {
		if (slot.name === 'emit') {
			this.emitActive = data
		}

		if (slot.name === 'eventName') {
			this.eventName = data
		}

		if (slot.name === 'data') {
			this.value = data
		}
	}

	RunTimeEventWriteContinuousPlugin.prototype.update_state = function() {
		if (this.eventName && this.value && this.emitActive) {
			E2.core.runtimeEvents.emit(this.eventName, this.value)
		}
	}

	E2.plugins.runtime_event_write_continuous = RunTimeEventWriteContinuousPlugin

})()
;
E2.p = E2.plugins["sample_and_hold_modulator"] = function(core, node)
{
	this.desc = 'Emits the input value when \'sample\' is true and emits the last sampled value otherwise. Emits zero by default.';
	
	this.input_slots = 
	[ 
		{ name: 'sample', dt: core.datatypes.BOOL, desc: 'Sending true to this slot updated the output value to match the input value, false inhibits input sampling.', def: true },
		{ name: 'value', dt: core.datatypes.FLOAT, desc: 'The input value.', def: 0.0 }
	];
	
	this.output_slots = [
		{ name: 'value', dt: core.datatypes.FLOAT, desc: 'The output value.', def: 0.0 }
	];
	
	this.state = { value: 0.0 };
};

E2.p.prototype.reset = function()
{
	this.has_updated = false;
	this.updated = true;
	this.last_state = true;
};

E2.p.prototype.update_input = function(slot, data)
{
	if(slot.index === 0)
		this.sample = data;
	else
		this.buffer = data;
};

E2.p.prototype.update_state = function()
{
	if(this.sample)
		this.state.value = this.buffer;
	else if(this.has_updated)
		this.updated = false;

	if(!this.sample && this.last_state)
	{
		this.last_state = this.sample;
		this.has_updated = false;
	}
};

E2.p.prototype.update_output = function(slot)
{
	this.has_updated = true;
	return this.state.value;
};	

E2.p.prototype.state_changed = function(ui)
{
	if(!ui)
	{
		this.state.value = 0.0;
		this.buffer = 0.0;
		this.sample = true;
	}
};

