E2.p.prototype.reset = function()
{
	this.scene = null;
	this.shader = null;
};

E2.p.prototype.update_input = function(slot, data)
{
	if(slot.index === 0)
	{
		if(data !== this.scene)
		{
			this.scene = data;
		
			if(!this.ext_camera)
				this.camera = this.scene.create_autofit_camera();
		}

		this.material_dirty = true;
	}
	else if(slot.index === 1)
	{
		this.material = data;
		
		if(!data)
		{
			this.material_caps = '';
			return;	
		}
		
		var caps = Material.get_caps_hash(null, data);
		
		if(this.material_caps !== caps)
		{
			this.material_caps = caps;
			this.material_dirty = true;
		}
	}
	else if(slot.index === 2)
	{
		this.camera = data;
		this.ext_camera = data ? true : false;
		
		if(!this.ext_camera && this.scene)
			this.camera = this.scene.create_autofit_camera();
	}
	else if(slot.index === 3)
		this.transform = data;
};

E2.p.prototype.connection_changed = function(on, conn, slot)
{
	if(!on)
	{
		if(slot.index === 0)
		{
			this.material_dirty = true;
		}
		else if(slot.index === 1)
		{
			this.material = null;
			this.material_caps = '';
			this.overload_shaders = null;
		}
	}
};

E2.p.prototype.update_state = function()
{
	if(this.scene)
	{
		if(this.material_dirty && this.material)
		{
			this.overload_shaders = this.scene.build_overload_shaders(this.material)
			this.material_dirty = false;
		}
		
		this.transform.invert = this.inv_transform;
		this.scene.render(this.gl, this.camera, this.transform, this.overload_shaders, this.material);
	}
};

E2.p.prototype.state_changed = function(ui)
{
	if(!ui)
	{
		this.material = null;
		this.material_caps = '';
		this.material_dirty = false;
		this.overload_shaders = null;
		this.camera = new Camera();
		this.transform = mat4.create();

		mat4.identity(this.transform);
		this.ext_camera = false;
		this.inv_transform = false;
	}
};


;
E2.p = E2.plugins["set_matrix_modulator"] = function(core, node)
{
	this.desc = 'Set matrix component.';
	
	this.input_slots = [ 
		{ name: 'matrix', dt: core.datatypes.MATRIX, desc: 'Matrix to set component of.', def: core.renderer.matrix_identity },
		{ name: 'row', dt: core.datatypes.FLOAT, desc: 'Row to set.', def: 0 },
		{ name: 'column', dt: core.datatypes.FLOAT, desc: 'Column to set.', def: 0 },
		{ name: 'value', dt: core.datatypes.FLOAT, desc: 'The value to set.', def: 0.0 }
	];
	
	this.output_slots = [
		{ name: 'matrix', dt: core.datatypes.MATRIX, desc: 'Modulated matrix.' }
	];
};

E2.p.prototype.update_input = function(slot, data)
{
	if(slot.index === 0)
		this.matrix = data;
	else if(slot.index === 1)
		this.row = data < 0 ? 0 : data > 3 ? 3 : data;
	else if(slot.index === 2)
		this.column = data < 0 ? 0 : data > 3 ? 3 : data;
	else if(slot.index === 3)
		this.value = data;
};	

E2.p.prototype.update_state = function()
{
	this.matrix[(this.row * 4) + this.column] = this.value;
};	

E2.p.prototype.update_output = function(slot)
{
	return this.matrix;
};

E2.p.prototype.state_changed = function(ui)
{
	if(!ui)
	{
		this.matrix = mat4.create();
		this.row = 0;
		this.column = 0;
		this.value = 0.0;
		
		mat4.identity(this.matrix);
	}
};

