E2.p = E2.plugins["translation_xyz_matrix"] = function(core, node)
{
	this.desc = 'Create a matrix that tranlates along the X, Y and Z axis.';
	
	this.input_slots = [ 
		{ name: 'x', dt: core.datatypes.FLOAT, desc: 'Amount to translate along the X-axis.', def: 0.0 },
		{ name: 'y', dt: core.datatypes.FLOAT, desc: 'Amount to translate along the Y-axis.', def: 0.0 },
		{ name: 'z', dt: core.datatypes.FLOAT, desc: 'Amount to translate along the Z-axis.', def: 0.0 }
	];
	
	this.output_slots = [
		{ name: 'matrix', dt: core.datatypes.MATRIX, desc: 'The resulting translation matrix.', def: core.renderer.matrix_identity }
	];
};

E2.p.prototype.reset = function()
{
	this.components = [0.0, 0.0, 0.0];
	this.matrix = mat4.create();

	mat4.identity(this.matrix);
};

E2.p.prototype.update_input = function(slot, data)
{
	this.components[slot.index] = data;
};

E2.p.prototype.update_state = function()
{
	var m = this.matrix;

	mat4.identity(this.matrix);
	
	m[12] = this.components[0];
	m[13] = this.components[1];
	m[14] = this.components[2];
};

E2.p.prototype.update_output = function(slot)
{
	return this.matrix;
};

;
E2.p = E2.plugins["transpose_matrix_modulator"] = function(core, node)
{
	this.desc = 'Emits the transposed version of the supplied <b>matrix</b>.';
	
	this.input_slots = [
		{ name: 'matrix', dt: core.datatypes.MATRIX, desc: 'The input matrix to be transposed.', def: core.renderer.matrix_identity }
	];
	
	this.output_slots = [
		{ name: 'transposed', dt: core.datatypes.MATRIX, desc: 'Emits the transposed input <b>matrix</b>.', def: core.renderer.matrix_identity }
	];
};

E2.p.prototype.reset = function()
{
	this.matrix = mat4.create();
	this.transposed = mat4.create();

	mat4.identity(this.matrix);
	mat4.identity(this.transposed);
};

E2.p.prototype.connection_changed = function(on, conn, slot)
{
	if(!on && slot.type === E2.slot_type.input)
	{
		mat4.identity(this.matrix);
		mat4.identity(this.transposed);
	}
};	

E2.p.prototype.update_input = function(slot, data)
{
	this.matrix = data;
};	

E2.p.prototype.update_state = function()
{
	mat4.transpose(this.matrix, this.transposed);
};	

E2.p.prototype.update_output = function(slot)
{
	return this.transposed;
};

;
E2.p = E2.plugins["triangle_modulator"] = function(core, node)
{
	this.desc = 'Triangle oscilator. A <b>time</b> value incrementing by one per second will yield a 1Hz output signal.';
	
	this.input_slots = [
		{ name: 'time', dt: core.datatypes.FLOAT, desc: 'The current time in seconds.', def: 0.0 }
	];
	
	this.output_slots = [
		{ name: 'value', dt: core.datatypes.FLOAT, desc: 'Emits ((0.5 - |(<b>time</b> % 1.0) - 0.5|) - 0.25) * 4.', def: 0.0 }
	];
};

E2.p.prototype.reset = function()
{
	this.time = 0.0;
	this.result = 0.0;
};

E2.p.prototype.update_input = function(slot, data)
{
	this.time = data;
};	

E2.p.prototype.update_state = function()
{
	this.result = ((0.5 - Math.abs(this.time % 1.0 - 0.5)) - 0.25) * 4.0;

};

E2.p.prototype.update_output = function(slot)
{
	return this.result;
};

