E2.p.prototype.update_view = function()
{
	if(!this.array)
	{
		this.dv = null;
		return;
	}

	var dv = this.dv = new DataView(this.array);

	this.accessor = [dv.getInt8,
			 dv.getUint8,
			 dv.getInt16,
			 dv.getUint16,
			 dv.getInt32,
			 dv.getUint32,
			 dv.getFloat32][this.state.datatype].bind(dv);
	this.stride = [1, 1, 2, 2, 4, 4, 4][this.state.datatype];
};

