(function() {
var UrlArray = E2.plugins["url_array_generator"] = function(core, node)
{
	Plugin.apply(this, arguments)
	this.desc = 'Load arbitrary data packed in an PNG from an URL.';
	
	this.input_slots = [];
	
	this.output_slots = [
		{ name: 'array', dt: core.datatypes.ARRAY, desc: 'The loaded array.' }
	];
	
	this.state = { url: '' };
	this.gl = core.renderer.context;
	this.core = core;
	this.array = null;
	this.dirty = false;
};
UrlArray.prototype = Object.create(Plugin.prototype)

UrlArray.prototype.reset = function()
{
};

UrlArray.prototype.create_ui = function()
{
	var inp = makeButton('Source', 'No texture selected.', 'url');
	var that = this;

	function clickHandler() {
		var oldValue = that.state.url
		var newValue = oldValue

		function setValue(v) {
			that.state.url = newValue = v
			that.updated = true
			that.state_changed()
		}

		FileSelectControl
		.createTextureSelector(oldValue, function(control) {
			control	
			.template('texture')
			.selected(oldValue)
			.onChange(setValue.bind(this))
			.buttons({
				'Cancel': setValue.bind(this, oldValue),
				'Select': setValue.bind(this)
			})
			.on('closed', function() {
				if (newValue === oldValue)
					return;
			
				that.undoableSetState('url', newValue, oldValue)
			})
			.modal()
		})
	}

	inp.click(clickHandler)

	return inp;
};

UrlArray.prototype.update_input = function(slot, data)
{
	this.state.url = data;
	this.state_changed(null);
};

UrlArray.prototype.update_state = function()
{
	if(!this.dirty)
		return;
		
	this.img = new Image();

	this.img.onload = function() {
		var canvas = document.createElement('canvas');
		var ctx = canvas.getContext('2d');
		
		canvas.width = this.img.width;
		canvas.height = this.img.height;
		
		ctx.imageSmoothingEnabled = false;
		ctx.webkitImageSmoothingEnabled = false;
		ctx.globalCompositeOperation = 'copy';
		
		ctx.drawImage(this.img, 0, 0);
	
		var pd = ctx.getImageData(0, 0, this.img.width, this.img.height);
		
		this.array = pd.data.buffer;
		this.array.stride = 1;
		this.array.datatype = 1;
		this.updated = true;

		msg('INFO: Finished loading data array from ' + this.img.src);
		
	}.bind(this);

	this.img.onerror = function(err) {
		console.error(err)
	}

	this.img.onabort = function() {}

	this.img.src = this.state.url;	
	this.dirty = false;
};

UrlArray.prototype.update_output = function() {
	return this.array;
};

UrlArray.prototype.state_changed = function(ui)
{
	if(this.state.url !== '')
	{
		if(ui)
			ui.attr('title', this.state.url);
		else
			this.dirty = true;
	}
};

})();

;
(function(){

var UrlAudioBuffer = E2.plugins.url_audio_buffer_generator = function(core, node) {
	Plugin.apply(this, arguments)
	this.desc = 'Load an audio sample from an URL.'

	this.input_slots = [
		{ name: 'url', dt: core.datatypes.TEXT, desc: 'Use this to load from a URL supplied as a string.', def: '' }
	]

	this.output_slots = [
		{ name: 'buffer', dt: core.datatypes.OBJECT, desc: 'An audio buffer.' }
	]

	this.state = { url: null }
	this.core = core
	this.buffer = null
	this.dirty = false
}

UrlAudioBuffer.prototype = Object.create(Plugin.prototype)

UrlAudioBuffer.prototype.reset = function() {
	this.updated = false
}

UrlAudioBuffer.prototype.create_ui = function() {
	var inp = makeButton('Source', 'No audio selected.', 'url')
	var that = this

	inp.click(function() {
		var fsc = FileSelectControl.createAudioSelector(that.state.url)
		fsc.onChange(function(v) {
			var actualFile = fsc.getFileMetadata(v)
			that.undoableSetState('url', actualFile.path, that.state.url)
		})
	})

	return inp
}

UrlAudioBuffer.prototype.update_input = function(slot, data) {
	this.state.url = data
	this.state_changed(null)
}

UrlAudioBuffer.prototype.update_state = function() {
	var that = this

	if (!this.dirty)
		return

	if (!this.state.url)
		return

	if (this.core.audioContext) {
		var noextname = this.state.url.substring(0, this.state.url.lastIndexOf('.'))
		var extname = this.state.url.substring(this.state.url.lastIndexOf('.'))

		// force Safari/iOS to use m4a *only if the asset is an ogg*
		// allows us to switch between ogg for everything else and m4a for Safari
		if (extname === '.ogg') {
			if (E2.util.isMobile.iOS() || E2.util.isBrowser.Safari()) {
				this.state.url = noextname + '.m4a'
			}
		}

		E2.core.assetLoader
		.loadAsset('audiobuffer', this.state.url)
		.then(function(buffer) {
			if (!buffer)
				return

			that.buffer = buffer
			that.updated = true
		})
	}
	else
		msg('ERROR: Cannot create audio buffer. This browser does not support the required API.')

	this.dirty = false
}

UrlAudioBuffer.prototype.update_output = function() {
	return this.buffer
}

UrlAudioBuffer.prototype.state_changed = function(ui) {
	if (this.state.url !== '') {
		if (ui)
			ui.attr('title', this.state.url)
		else
			this.dirty = true
	}
}

})()

;
(function(){
var UrlAudio = E2.plugins["url_audio_generator"] = function(core, node)
{
	Plugin.apply(this, arguments)
	this.desc = 'Load a sample from an URL. Each sample should be encoded as .wav, .mp3, .mp4 and .ogg, and no extension should be specified. This plugin will load the appropriate filetype for the current execution environment. Hover over the Source button to see the url of the current file.';

	this.input_slots = [
		{ name: 'url', dt: core.datatypes.TEXT, desc: 'Use this to load from a URL supplied as a string.', def: '' }
	];
	
	this.output_slots = [ 
		{ name: 'audio', dt: core.datatypes.AUDIO, desc: 'An audio stream.' }
	];
	
	this.state = { url: '' };
	this.core = core;
	this.audio = null;
	this.dirty = false;
};
UrlAudio.prototype = Object.create(Plugin.prototype)

UrlAudio.prototype.reset = function()
{
};

UrlAudio.prototype.create_ui = function()
{
	var inp = makeButton('Source', 'No audio selected.', 'url');
	var that = this;

	function clickHandler() {
		var oldValue = that.state.url
		var newValue = oldValue

		function setValue(v) {
			that.state.url = newValue = v
			that.updated = true
			that.state_changed()
		}

		FileSelectControl
		.createModelSelector('audio', oldValue, function(control) {
			control	
			.selected(oldValue)
			.onChange(setValue.bind(this))
			.buttons({
				'Cancel': setValue.bind(this, oldValue),
				'Select': setValue.bind(this)
			})
			.on('closed', function() {
				if (newValue === oldValue)
					return;
			
				that.undoableSetState('url', newValue, oldValue)

				E2.track({
					event: 'assetChanged',
					plugin: 'UrlAudio',
					url: newValue
				})
			})
			.modal()
		})
	}

	inp.click(clickHandler)
	return inp;
};

UrlAudio.prototype.update_input = function(slot, data)
{
	this.state.url = data;
	this.state_changed(null);
};

UrlAudio.prototype.update_state = function()
{
	var that = this;

	if(!this.dirty)
		return;
	
	if (typeof(Audio) === 'undefined')
		return msg('Audio: This browser does not support the Audio API.');
	
	if (this.audio)
	{
		this.audio.pause();
		delete this.audio;
	}

	this.audio = new Audio();

	this.audio.loop = true;
	this.audio.preload = true;

	if (this.state.url)
	{
		this.audio.addEventListener('error', function()
		{
			msg('ERROR: Audio: Failed to load \'' + that.state.url + '\'.');
			that.state.url = '';
			that.audio = null;
		});
	
		msg('Audio: Loading ' + this.state.url + '.');
		this.audio.src = this.state.url;
	}
	
	this.dirty = false;
};

UrlAudio.prototype.update_output = function(slot)
{
	return this.audio;
};

UrlAudio.prototype.state_changed = function(ui)
{
	if (this.state.url) {
		if(ui)
			ui.attr('title', this.state.url);
		else
			this.dirty = true;
	}
};
})();

